import csv
from datetime import datetime

# Read all expense data from CSV-like files
expenses = []
for f in ['expenses.csv', 'travel_data.csv', 'expense_log.csv']:
    if not any(f.endswith(ext) for ext in ['csv', 'xlsx', 'xls']) and os.path.exists(f):
        continue
    try:
        with open(f, 'r') as fp:
            reader = csv.DictReader(fp)
            for row in reader:
                expenses.append(row)
    except:
        pass

# Filter: Travel type and date between 2026-01-01 and 2026-03-31
travel_expenses = []
for e in expenses:
    if e.get('Type','').strip() == 'Travel':
        # Parse date - format might be YYYY-MM-DD
        try:
            dt = datetime.strptime(e['Date'], '%Y-%m-%d')
            if 2026 <= dt.year <= 2026 and dt.month < 4:  # Jan-Mar 2026
                travel_expenses.append(e)
        except:
            pass

print(f'Total Travel expenses in 2026-01-01 to 2026-03-31: {len(travel_expenses)}')
for e in travel_expenses:
    print(f\"  ID={e['ID']}, Date={e['Date']}, Amount={e['Amount']}, Currency={e['Currency']}\")
